from base import *
body=cap("Peek · right after ⌘⇧4")+compact('<span>▤ 3</span>','',peek='<span>Screenshot added to the Shelf</span><span class="s">drag it anywhere</span>',h_scene=96)
th=lambda inner,lbl:f'<div style="width:88px;text-align:center"><div style="height:66px;border-radius:9px;border:1px solid rgba(255,255,255,.08);overflow:hidden">{inner}</div><div class="s" style="font-size:11px;margin-top:5px">{lbl}</div></div>'
shot='<div style="height:100%;background:linear-gradient(135deg,#4a6a9a,#c89a7a);display:flex;align-items:center;justify-content:center"><div style="width:60%;height:55%;background:rgba(255,255,255,.85);border-radius:4px"></div></div>'
inner='<div style="display:flex;gap:12px;align-items:flex-start">'+th(shot,'Screenshot 10.04')+th('<div style="height:100%;background:rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;font-size:12px">PDF</div>','Invoice.pdf')+th('<div style="height:100%;background:rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;font-size:12px">🔗︎</div>','github.com')+'<div style="flex:1"></div><div style="display:flex;flex-direction:column;gap:6px"><span class="pill">AirDrop</span><span class="pill">Convert…</span><span class="pill">Copy</span></div></div>'
body+=cap("Open notch · Shelf, newest screenshot first")+opened(inner,tabs='<span>♫</span><span class="on">▤</span><span>◷</span>')
body+=cap("Setting")+'<div class="card" style="width:520px;font-size:13px;display:flex;justify-content:space-between;align-items:center"><div><b>Catch new screenshots</b><div class="note" style="margin-top:3px">From your screenshot folder (Desktop). Shelf keeps up to 20 items.</div></div><span style="width:38px;height:22px;border-radius:11px;background:#f5f5f5;position:relative"><span style="position:absolute;right:2px;top:2px;width:18px;height:18px;border-radius:50%;background:#111"></span></span></div>'
open("m08.html","w").write(page("Shelf: catch new screenshots","New screenshots land on the Shelf, one drag from anywhere.",body))
